"""
Bundle formatters for LLM prompt ingestion (Markdown, XML, JSON).
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import List


@dataclass
class FileContextItem:
    relative_path: str
    original_code: str
    compressed_code: str
    original_tokens: int
    compressed_tokens: int


def format_markdown(items: List[FileContextItem]) -> str:
    """Formats bundled files into clean GitHub-flavored markdown."""
    blocks: List[str] = [
        "# Codebase Context Bundle",
        "> Generated by CodeShave (https://github.com/jaideepkrishna2008-ui/codeshave)",
        "",
    ]

    for item in items:
        pct = (
            (1.0 - (item.compressed_tokens / item.original_tokens)) * 100.0
            if item.original_tokens > 0
            else 0.0
        )
        blocks.append(
            f"### File: `{item.relative_path}` "
            f"*(Tokens: {item.compressed_tokens:,} | -{pct:.1f}% reduction)*"
        )
        blocks.append(f"```python\n{item.compressed_code}\n```\n")

    return "\n".join(blocks)


def format_xml(items: List[FileContextItem]) -> str:
    """
    Formats bundled files into Claude / Anthropic standard XML document tagging,
    which optimizes prompt recall in multi-turn dialogues.
    """
    lines: List[str] = ["<documents>"]
    for idx, item in enumerate(items, 1):
        lines.append(f'  <document index="{idx}">')
        lines.append(f"    <source>{item.relative_path}</source>")
        lines.append("    <document_content>")
        lines.append(item.compressed_code)
        lines.append("    </document_content>")
        lines.append("  </document>")
    lines.append("</documents>")
    return "\n".join(lines)


def format_json(items: List[FileContextItem]) -> str:
    """Formats bundled items as JSON for programmatic agent ingestion."""
    data = [
        {
            "path": item.relative_path,
            "content": item.compressed_code,
            "metrics": {
                "original_tokens": item.original_tokens,
                "compressed_tokens": item.compressed_tokens,
                "saved_tokens": max(0, item.original_tokens - item.compressed_tokens),
            },
        }
        for item in items
    ]
    return json.dumps({"codeshave_version": "0.1.0", "files": data}, indent=2)


def format_bundle(items: List[FileContextItem], output_format: str = "markdown") -> str:
    fmt = output_format.lower().strip()
    if fmt == "xml":
        return format_xml(items)
    elif fmt == "json":
        return format_json(items)
    return format_markdown(items)
